2	 * Functions for manipulating the global configuration file, which lives at
3	 * ~/.promptfoo/promptfoo.yaml by default.
4	 */
5	import * as fs from 'fs';
6	import * as path from 'path';
7	
8	import yaml from 'js-yaml';
9	import { getConfigDirectoryPath } from '../util/config/manage';
10	
11	import type { GlobalConfig } from '../configTypes';
12	
13	export function writeGlobalConfig(config: GlobalConfig): void {
14	  fs.writeFileSync(
15	    path.join(getConfigDirectoryPath(true), 'promptfoo.yaml') /* createIfNotExists */,
16	    yaml.dump(config),
17	  );
18	}
19	
20	export function readGlobalConfig(): GlobalConfig {
21	  const configDir = getConfigDirectoryPath();
22	  const configFilePath = path.join(configDir, 'promptfoo.yaml');
23	  let globalConfig: GlobalConfig = { id: crypto.randomUUID() };
24	  if (fs.existsSync(configFilePath)) {
25	    globalConfig = (yaml.load(fs.readFileSync(configFilePath, 'utf-8')) as GlobalConfig) || {};
26	    if (!globalConfig?.id) {
27	      globalConfig = { ...globalConfig, id: crypto.randomUUID() };
28	      writeGlobalConfig(globalConfig);
29	    }
30	  } else {
31	    if (!fs.existsSync(configDir)) {
32	      fs.mkdirSync(configDir, { recursive: true });
33	    }
34	    fs.writeFileSync(configFilePath, yaml.dump(globalConfig));
35	  }
36	
37	  return globalConfig;
38	}
