40	/**
41	 * Merges the top-level keys into existing config.
42	 * @param partialConfig New keys to merge into the existing config.
43	 */
44	export function writeGlobalConfigPartial(partialConfig: Partial<GlobalConfig>): void {
45	  const currentConfig = readGlobalConfig();
46	  // Create a shallow copy of the current config
47	  const updatedConfig: GlobalConfig = { ...currentConfig };
48	
49	  // Use Object.entries for better type safety
50	  Object.entries(partialConfig).forEach(([key, value]) => {
51	    if (value !== undefined && value !== null) {
52	      // Type assertion: we know key is valid from partialConfig, and value matches the key's type
53	      (updatedConfig as Record<string, unknown>)[key] = value;
54	    } else {
55	      // Remove the property if value is falsy
56	      delete (updatedConfig as Record<string, unknown>)[key];
57	    }
58	  });
59	
60	  writeGlobalConfig(updatedConfig);
61	}
