133	export async function checkEmailStatus(options?: {
134	  validate?: boolean;
135	}): Promise<EmailStatusResult> {
136	  const { default: telemetry } = await import('../telemetry');
137	  const ciMode = isCI();
138	  const userEmail = ciMode ? CI_PLACEHOLDER_EMAIL : getUserEmail();
139	
140	  if (!userEmail) {
141	    return {
142	      status: NO_EMAIL_STATUS,
143	      hasEmail: false,
144	      message: 'Redteam evals require email verification. Please enter your work email:',
145	    };
146	  }
147	
148	  if (ciMode) {
149	    // CI uses a synthetic placeholder to avoid interactive prompts. Treat it as
150	    // already validated so test runs do not depend on live account state.
151	    return {
152	      status: EmailValidationStatus.OK,
153	      hasEmail: true,
154	      email: userEmail,
155	    };
156	  }
157	
158	  try {
159	    const validateParam = options?.validate ? '&validate=true' : '';
160	    // Use longer timeout when validation is requested
161	    const timeout = options?.validate ? 3000 : 500;
162	
163	    // Log when we're validating the email since it can take a sec
164	    if (options?.validate) {
165	      logger.info(`Checking email...`);
166	    }
167	
168	    const host = getEnvString('PROMPTFOO_CLOUD_API_URL', 'https://api.promptfoo.app');
169	
170	    const resp = await fetchWithTimeout(
171	      `${host}/api/users/status?email=${encodeURIComponent(userEmail)}${validateParam}`,
172	      undefined,
173	      timeout,
174	    );
175	    const data = (await resp.json()) as {
176	      status: EmailValidationStatus;
177	      message?: string;
178	      error?: string;
179	    };
180	
181	    if (options?.validate) {
182	      const invalidStatuses: Set<EmailValidationStatus> = new Set([
183	        EmailValidationStatus.RISKY_EMAIL,
184	        EmailValidationStatus.DISPOSABLE_EMAIL,
185	        EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED,
186	      ]);
187	      if (invalidStatuses.has(data.status)) {
188	        if (data.status === EmailValidationStatus.EMAIL_VERIFICATION_REQUIRED) {
189	          setUserEmailValidated(false);
190	          setUserEmailNeedsValidation(true);
191	        }
192	        // Tracking filtered emails via this telemetry endpoint for now to guage sensitivity of validation
193	        // We should take it out once we're happy with the sensitivity
194	        if (
195	          data.status === EmailValidationStatus.RISKY_EMAIL ||
196	          data.status === EmailValidationStatus.DISPOSABLE_EMAIL
197	        ) {
198	          await telemetry.saveConsent(userEmail, {
199	            source: 'filteredInvalidEmail',
200	          });
201	        }
202	      } else {
203	        setUserEmailValidated(true);
204	        // Track the validated email via telemetry
205	        await telemetry.saveConsent(userEmail, {
206	          source: 'promptForEmailValidated',
207	        });
208	      }
209	    }
210	
211	    return {
212	      status: data.status,
213	      message: data.message ?? data.error,
214	      email: userEmail,
215	      hasEmail: true,
216	    };
217	  } catch (e) {
218	    logger.debug(`Failed to check user status: ${e}`);
219	    // If we can't check status, assume it's OK but log the issue
220	    return {
221	      status: EmailValidationStatus.OK,
222	      message: 'Unable to verify email status, but proceeding',
223	      email: userEmail,
224	      hasEmail: true,
225	    };
226	  }
227	}
