42	function getPostHogClient(): PostHog | null {
43	  if (getEnvBool('PROMPTFOO_DISABLE_TELEMETRY') || getEnvBool('IS_TESTING')) {
44	    return null;
45	  }
46	
47	  if (posthogClient === null && POSTHOG_KEY) {
48	    try {
49	      posthogClient = new PostHog(POSTHOG_KEY, {
50	        host: EVENTS_ENDPOINT,
51	        fetch: fetchWithProxy,
52	        // Disable automatic flush interval to prevent keeping the event loop alive.
53	        // Without this, PostHog's internal setInterval keeps the Node.js event loop
54	        // alive indefinitely, causing processes that import promptfoo to hang.
55	        // Events are still sent immediately via explicit flush() calls after each capture.
56	        // See: https://github.com/promptfoo/promptfoo/issues/5893
57	        flushInterval: 0,
58	      });
59	    } catch {
60	      posthogClient = null;
61	    }
62	  }
63	  return posthogClient;
64	}
